cat > sim/run.sh <<'EOF'
#!/bin/bash
# usage: run.sh <check.json> <scenario>: prints each expectation's value over the simulated record
here=$(cd "$(dirname "$0")/.." && pwd)
rec=$(jq -n --rawfile defs "$here/defs.jq" --arg scenario "$2" -f "$here/sim/record.jq") || exit 2
jq -r '.steps | to_entries[] | .key as $s | .value.expect | to_entries[] | "\($s)\t\(.key)\t\(.value.that)"' "$1" |
while IFS=$'\t' read -r s e that; do
  printf '%s step %s expect %s: %s\n' "$2" "$s" "$e" "$(jq "$that" <<<"$rec" 2>&1 | head -c 200)"
done
EOF
